CREATE DATABASE IF NOT EXISTS studenthub; USE studenthub; CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100),email VARCHAR(150) UNIQUE,role ENUM('student','admin') DEFAULT 'student',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP); CREATE TABLE events(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(150)); CREATE TABLE audit_logs(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT,action VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);